<?php
require_once 'config.php'; require_login(); if(!is_admin()){http_response_code(403);exit('Access denied');}$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($_POST['action']==='user'){ $hash=password_hash($_POST['password'],PASSWORD_DEFAULT);$st=$pdo->prepare("INSERT INTO users(name,username,password,role) VALUES(?,?,?,?)");$st->execute([trim($_POST['name']),trim($_POST['username']),$hash,$_POST['role']]);flash('ব্যবহারকারী created.');}
elseif($_POST['action']==='assign'){$pid=(int)$_POST['project_id'];$uid=(int)$_POST['user_id'];$fields=['view_project','add_expense','edit_expense','delete_expense','add_head','view_report','approve_expense','close_project'];$vals=[];foreach($fields as $f)$vals[]=isset($_POST[$f])?1:0;$sql="INSERT INTO project_assignments(project_id,user_id,".implode(',',$fields).") VALUES(?,?,".implode(',',array_fill(0,count($fields),'?')).") ON DUPLICATE KEY UPDATE ".implode(',',array_map(fn($f)=>"$f=VALUES($f)",$fields));$st=$pdo->prepare($sql);$st->execute(array_merge([$pid,$uid],$vals));flash('প্রকল্প permissions saved.');}redirect('users.php');}
$users=$pdo->query("SELECT id,name,username,role,active FROM users ORDER BY id DESC")->fetchAll();$projects=$pdo->query("SELECT id,title FROM projects ORDER BY title")->fetchAll();$assignments=$pdo->query("SELECT a.*,u.name user_name,p.title project_title FROM project_assignments a JOIN users u ON u.id=a.user_id JOIN projects p ON p.id=a.project_id ORDER BY p.title,u.name")->fetchAll();include 'layout_top.php';?>
<section class="page-title"><div><span class="eyebrow">ব্যবহারকারী নিয়ন্ত্রণ</span><h1>ব্যবহারকারী ও অনুমতি</h1><p>ব্যবহারকারী তৈরি করুন এবং প্রতিটি প্রকল্পের জন্য আলাদা অনুমতি দিন।</p></div></section>
<section class="panel"><div class="panel-head"><h2>ব্যবহারকারী তৈরি</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user"><div><label>পুরো নাম</label><input name="name" required></div><div><label>ব্যবহারকারীর নাম</label><input name="username" required></div><div><label>প্রাথমিক পাসওয়ার্ড</label><input type="password" name="password" minlength="8" required></div><div><label>ভূমিকা</label><select name="role"><?php foreach(['owner','cashier','employee','engineer','project_head'] as $r):?><option value="<?=$r?>"><?=e(ucwords(str_replace('_',' ',$r)))?></option><?php endforeach;?></select></div><button class="btn primary">ব্যবহারকারী তৈরি</button></form></section>
<section class="panel"><div class="panel-head"><h2>প্রকল্পের অনুমতি নির্ধারণ</h2></div><?php if($projects&&$users):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="assign"><div class="form-grid"><div><label>প্রকল্প</label><select name="project_id"><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=e($p['title'])?></option><?php endforeach;?></select></div><div><label>ব্যবহারকারী</label><select name="user_id"><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['name'])?> (<?=e($u['username'])?>)</option><?php endforeach;?></select></div></div><div class="permission-grid"><?php foreach(['view_project'=>'প্রকল্প দেখা','add_expense'=>'ব্যয় যোগ','edit_expense'=>'ব্যয় সম্পাদনা','delete_expense'=>'ব্যয় মুছুন','add_head'=>'ব্যয় যোগ head','view_report'=>'প্রতিবেদন দেখা','approve_expense'=>'ব্যয় অনুমোদন','close_project'=>'প্রকল্প বন্ধ'] as $k=>$v):?><label class="check"><input type="checkbox" name="<?=$k?>" value="1"> <?=$v?></label><?php endforeach;?></div><button class="btn primary">অনুমতি সংরক্ষণ</button></form><?php else:?><p class="empty">Create at least one project and one user first.</p><?php endif;?></section>
<section class="panel"><div class="panel-head"><h2>বর্তমান দায়িত্ব বণ্টন</h2></div><div class="table-wrap"><table><thead><tr><th>ব্যবহারকারী</th><th>প্রকল্প</th><th>Permissions</th></tr></thead><tbody><?php foreach($assignments as $a):$perms=[];foreach(['view_project'=>'View','add_expense'=>'ব্যয় যোগ','edit_expense'=>'Edit','delete_expense'=>'Delete','add_head'=>'Add head','view_report'=>'Report','approve_expense'=>'Approve','close_project'=>'Close'] as $k=>$v)if($a[$k])$perms[]=$v;?><tr><td><?=e($a['user_name'])?></td><td><?=e($a['project_title'])?></td><td><?=e(implode(', ',$perms))?></td></tr><?php endforeach;?><?php if(!$assignments):?><tr><td colspan="3" class="empty">এখনো কোনো প্রকল্পে দায়িত্ব দেওয়া হয়নি.</td></tr><?php endif;?></tbody></table></div></section><?php include 'layout_bottom.php';?>
